  except detail;
  // no ticket open - just print
endif;

if flag = 'Y';
  close EXCPTFLT;
endif;

// leftover debug
if flag2 = 'Y';
  line = 'debug vip skip on';
  except detail;
endif;

*inlr = *on;
return;

